mapper.select:
SELECT * FROM room
WHERE hotel_id = #{hotelId}
  AND type_name = #{typeName}
  AND status = 1
  AND id NOT IN (
    SELECT room_id FROM hotel_order
    WHERE status IN (1, 2) -- 正在预约或已入住的均视为占用
      AND NOT (start_date >= #{endDate} OR end_date <= #{startDate})
)
    LIMIT 1

mapper.insert:
INSERT INTO hotel_order (
    order_no, user_id, hotel_id, room_id, start_date, end_date, total_amount, status
) VALUES (
             #{orderNo}, #{userId}, #{hotelId}, #{roomId}, #{startDate}, #{endDate}, #{totalAmount}, #{status}
         )

mapper.select:
SELECT * FROM hotel_order
WHERE user_id = #{userId}
ORDER BY create_time DESC

mapper.update:
UPDATE hotel_order
SET status = #{status}
WHERE id = #{id}
